1	package pricing
2	
3	import "fmt"
4	
5	// Line is one invoice line: a quantity and a unit price as written.
6	type Line struct {
7		Qty   int
8		Price string
9	}
10	
11	// Total sums the lines, applies the tier discount and formats the result
12	// as "$<dollars>.<cents>".
13	func Total(lines []Line) (string, error) {
14		sub := 0
15		for _, l := range lines {
16			c, err := ParseCents(l.Price)
17			if err != nil {
18				return "", err
19			}
20			sub += c * l.Qty
21		}
22		final := Apply(sub)
23		return fmt.Sprintf("$%d.%02d", final/100, final%100), nil
24	}

