package norm

import (
	"strings"
	"unicode"
)

// Options controls how Normalize processes a string.
type Options struct {
	Lower      bool // ASCII-lowercase letters
	Collapse   bool // collapse runs of whitespace to single space
	StripPunct bool // delete every ASCII punctuation byte
}

// Default returns options with Lower and Collapse true, StripPunct false.
func Default() Options { return Options{Lower: true, Collapse: true} }

// Normalize applies p's options in order: strip-punctuation → collapse
// whitespace → lowercase, then always trims both ends. A zero Options
// only trims.
func Normalize(s string, p Options) string {
	if p.StripPunct {
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			if !strings.ContainsByte(`!"#$%&'()*+,-./:;<=>?@[\\]^_`+"`"+{|}~`, s[i]) {
				b.WriteByte(s[i])
			}
		}
		s = b.String()
	}

	if p.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}

	if p.Lower {
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			c := s[i]
			if c >= 'A' && c <= 'Z' {
				c += 'a' - 'A'
			}
			b.WriteByte(c)
		}
		s = b.String()
	}

	return strings.TrimSpace(s)
}

var _ = unicode.ASCII

