package norm

import "testing"

func TestNormalizeLowercasesAndCollapses(t *testing.T) {
	if got := Normalize("  Hello   World  ", Options{}); got != "hello world" {
		t.Fatalf("got %q", got)
	}
}

func TestNormalizeKeepsPunctuation(t *testing.T) {
	if got := Normalize("Hello, World!", Options{}); got != "hello, world!" {
		t.Fatalf("got %q", got)
	}
}

package main

import (
	"fmt"
	"os"
	"strings"

	"example.com/textpipe/norm"
)

func main() {
	fmt.Println(norm.Normalize(strings.Join(os.Args[1:], " "), norm.Default()))
}

package index

import (
	"sort"
	"strings"

	"example.com/textpipe/norm"
)

// Build maps each normalised word to the sorted document numbers it
// appears in.
func Build(docs []string) map[string][]int {
	out := map[string][]int{}
	for i, d := range docs {
		seen := map[string]bool{}
		for _, w := range strings.Split(norm.Normalize(d, norm.Default()), " ") {
			if w == "" || seen[w] {
				continue
			}
			seen[w] = true
			out[w] = append(out[w], i)
		}
	}
	for _, v := range out {
		sort.Ints(v)
	}
	return out
}

package report

import (
	"strings"

	"example.com/textpipe/norm"
)

// Render joins the normalised titles with "; ".
func Render(titles []string) string {
	out := make([]string, 0, len(titles))
	for _, t := range titles {
		n := norm.Normalize(t, norm.Default())
		if n == "" {
			continue
		}
		out = append(out, n)
	}
	return strings.Join(out, "; ")
}

