package norm

import "strings"

// Options controls how Normalize processes a string.
type Options struct {
	// Lower when true, ASCII-lowercases the result.
	Lower bool
	// Collapse when true, collapses runs of whitespace to a single space.
	Collapse bool
	// StripPunct when true, deletes ASCII punctuation bytes.
	StripPunct bool
}

// Default returns Options with Lower and Collapse enabled and
// StripPunct disabled. Using the default produces the same behaviour as
// the original Normalize function.
func Default() Options {
	return Options{Lower: true, Collapse: true}
}

// Normalize applies the configured options in the fixed order:
// StripPunct → Collapse → Lower, then always trims both ends.
// A zero Options only trims whitespace from the ends.
func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch {
			case c >= '!' && c <= '/': // !"#$%&'()*+,-./
				continue
			case c >= ':' && c <= '@':
				continue
			case c == '[' || c == '\\':
				continue
			case c == ']':
				continue
			case c >= '^' && c <= '_':
				continue
			case c == '`':
				continue
			case c >= '{' && c <= '~':
				continue
			default:
				b.WriteByte(c)
			}
		}
		s = b.String()
	}
	if opt.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}
	if opt.Lower {
		s = strings.ToLower(s)
	}
	return strings.TrimSpace(s)
}

