package norm

import (
	"strings"
	"unicode/utf8"
)

// Options configures Normalize's behaviour.  Zero values trim only.
type Options struct {
	Lower      bool
	Collapse   bool
	StripPunct bool
}

// Default returns Options that lowercases, collapses whitespace, and trims.
func Default() Options {
	return Options{Lower: true, Collapse: true}
}

const punct = `!"#$%&'()*+,-./:;<=>?@[\\]^_` + "`" + `{|}~`

// Normalize processes s according to opts and always trims the result.
func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var out strings.Builder
		out.Grow(len(s))
		for i := 0; i < len(s); i++ {
			if !strings.ContainsRune(punct, rune(s[i])) {
				out.WriteByte(s[i])
			}
		}
		s = out.String()
	}
	if opt.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}
	if opt.Lower {
		s = strings.ToLower(s)
	}
	s = strings.TrimSpace(s)
	return s
}

