import sys
import re
from collections import Counter

def main():
    # Parse arguments: options before or after FILE
    args = sys.argv[1:]
    min_count = None
    top_n = None
    exclude_words = set()
    filename = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--min':
            i += 1
            min_count = int(args[i])
        elif arg == '--top':
            i += 1
            top_n = int(args[i])
        elif arg == '--exclude':
            i += 1
            raw = args[i]
            for w in raw.split(','):
                if w:
                    exclude_words.add(w.lower())
        elif arg.startswith('--'):
            # unknown option, skip it
            pass
        else:
            filename = arg
        i += 1

    if filename is None:
        print("tally: no such file: -", file=sys.stderr)
        sys.exit(2)

    # Read file
    try:
        f = open(filename, 'r')
    except (FileNotFoundError, IsADirectoryError, PermissionError, OSError):
        print(f"tally: no such file: {filename}", file=sys.stderr)
        sys.exit(2)

    text = f.read()
    f.close()

    # Split into words: maximal runs of [A-Za-z0-9_]
    words = re.findall(r'[A-Za-z0-9_]+', text)
    words = [w.lower() for w in words]

    counter = Counter(words)

    # Apply --exclude (case-insensitive already since we lowercased everything)
    for w in list(counter.keys()):
        if w in exclude_words:
            del counter[w]

    # Filter by --min
    if min_count is not None:
        for w in list(counter.keys()):
            if counter[w] < min_count:
                del counter[w]

    # Sort: by count descending, then word ascending
    result = sorted(counter.items(), key=lambda x: (-x[1], x[0]))

    # Apply --top
    if top_n is not None:
        result = result[:top_n]

    # Print
    for word, count in result:
        print(f"{count} {word}")

    sys.exit(0)

if __name__ == '__main__':
    main()

