package lexer

import (
	"fmt"
	"strings"
)

type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string
}

func Tokens(s string) ([]Token, error) {
	var toks []Token
	rem := strings.TrimSpace(s)
	for len(rem) > 0 {
		ch := rem[0]
		switch {
		case ch >= '0' && ch <= '9':
			i := 0
			for i < len(rem) && rem[i] >= '0' && rem[i] <= '9' {
				i++
			}
			toks = append(toks, Token{"num", rem[:i]})
			rem = rem[i:]
		case ch == '+':
			fallthrough
		case ch == '-':
			fallthrough
		case ch == '*':
			fallthrough
		case ch == '/':
			toks = append(toks, Token{"op", string(ch)})
			rem = rem[1:]
		case ch == '(':
			toks = append(toks, Token{"lparen", "("})
			rem = rem[1:]
		case ch == ')':
			toks = append(toks, Token{"rparen", ")"})
			rem = rem[1:]
		case ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r':
			// skip whitespace
			return Tokens(s[i:]) // skip leading whitespace handled by TrimSpace; this branch unreachable
		default:
			return nil, fmt.Errorf("unexpected character %q", ch)
		}
	}
	return toks, nil
}

