package parser

import (
	"errors"
	"fmt"

	"example.com/expr/lexer"
)

// Node is an expression AST node.
type Node interface {
	isNode()
}

// NumLit is a numeric literal node.
type NumLit struct {
	Value int
}

func (*NumLit) isNode() {}

// BinaryExpr is a binary operation node.
type BinaryExpr struct {
	Op    string // "+", "-", "*", "/"
	Left  Node
	Right Node
}

func (*BinaryExpr) isNode() {}

var errSyntax = errors.New("syntax error")

// Parse parses a token slice into an expression tree.
// Operands are parsed left-to-right; * and / bind tighter than + and -.
// Parentheses group sub-expressions.
func Parse(toks []lexer.Token) (Node, error) {
	if toks == nil || len(toks) == 0 {
		return nil, errSyntax
	}
	p := &parser{toks: toks, pos: 0}
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, fmt.Errorf("unexpected token %q after expression", p.toks[p.pos].Text)
	}
	return node, nil
}

type parser struct {
	toks []lexer.Token
	pos  int
}

func (p *parser) peek() (*lexer.Token, error) {
	if p.pos >= len(p.toks) {
		return nil, errSyntax
	}
	return &p.toks[p.pos], nil
}

func (p *parser) advance() (*lexer.Token, error) {
	if p.pos >= len(p.toks) {
		return nil, errSyntax
	}
	tok := p.toks[p.pos]
	p.pos++
	return &tok, nil
}

func (p *parser) expect(kind string) (*lexer.Token, error) {
	tok, err := p.advance()
	if err != nil {
		return nil, err
	}
	if tok.Kind != kind {
		return nil, fmt.Errorf("expected %q but got %q", kind, tok.Kind)
	}
	return tok, nil
}

// parseExpr implements precedence climbing for
//   expr       : term (('+' | '-') term)*
//   term       : factor (('*' | '/') factor)*
//   factor     : NUM | '(' expr ')'
func (p *parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.Kind != "op" || (tok.Text != "+" && tok.Text != "-") {
			break
		}
		opTok, _ := p.advance()
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: opTok.Text, Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseTerm() (Node, error) {
	left, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.Kind != "op" || (tok.Text != "*" && tok.Text != "/") {
			break
		}
		opTok, _ := p.advance()
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: opTok.Text, Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseFactor() (Node, error) {
	tok, err := p.peek()
	if err != nil {
		return nil, err
	}

	switch tok.Kind {
	case "num":
		_, _ = p.advance()
		return &NumLit{Value: 0}, nil // fill in value after parsing num

	case "lparen":
		_, _ = p.advance()
		node, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		closeTok, err := p.expect("rparen")
		if err != nil {
			return nil, err
		}
		_ = closeTok
