package lexer

import (
	"errors"
	"fmt"
)

type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string
}

func Tokens(s string) ([]Token, error) {
	var toks []Token
	i := 0
	for i < len(s) {
		ch := s[i]
		switch {
		case ch >= '0' && ch <= '9':
			start := i
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
			toks = append(toks, Token{"num", s[start:i]})
		case ch == '+' || ch == '-' || ch == '*' || ch == '/':
			toks = append(toks, Token{"op", string(ch)})
			i++
		case ch == '(':
			toks = append(toks, Token{"lparen", "("})
			i++
		case ch == ')':
			toks = append(toks, Token{"rparen", ")"})
			i++
		case ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r':
			i++
		default:
			return nil, fmt.Errorf("unexpected character %q", ch)
		}
	}
	if len(toks) == 0 {
		return nil, nil
	}
	return toks, nil
}

var ErrSyntax = errors.New("syntax error")

