package parser

import (
	"fmt"
	"strconv"

	"example.com/expr/lexer"
)

// Node is an expression AST node.
type Node interface {
	isNode()
}

// NumLit represents a numeric literal.
type NumLit struct {
	Value int
}

func (*NumLit) isNode() {}

// BinaryExpr represents a binary operation.
type BinaryExpr struct {
	Op    string // "+", "-", "*", "/"
	Left  Node
	Right Node
}

func (*BinaryExpr) isNode() {}

// Parse parses a token slice into an expression tree.
// * and / bind tighter than + and -. Equal-precedence operators associate left.
// Parentheses group sub-expressions.
func Parse(toks []lexer.Token) (Node, error) {
	if toks == nil || len(toks) == 0 {
		return nil, fmt.Errorf("empty input")
	}
	p := &parser{toks: toks, pos: 0}
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, fmt.Errorf("unexpected token %q after expression", p.toks[p.pos].Text)
	}
	return node, nil
}

type parser struct {
	toks []lexer.Token
	pos  int
}

func (p *parser) peek() *lexer.Token {
	if p.pos >= len(p.toks) {
		return nil
	}
	return &p.toks[p.pos]
}

func (p *parser) advance() *lexer.Token {
	if p.pos >= len(p.toks) {
		return nil
	}
	tok := p.toks[p.pos]
	p.pos++
	return &tok
}

// parseExpr -> term (('+' | '-') term)*
func (p *parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok == nil {
			break
		}
		if tok.Kind != "op" || (tok.Text != "+" && tok.Text != "-") {
			break
		}
		opTok := p.advance()
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: opTok.Text, Left: left, Right: right}
	}
	return left, nil
}

// parseTerm -> factor (('*' | '/') factor)*
func (p *parser) parseTerm() (Node, error) {
	left, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok == nil {
			break
		}
		if tok.Kind != "op" || (tok.Text != "*" && tok.Text != "/") {
			break
		}
		opTok := p.advance()
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: opTok.Text, Left: left, Right: right}
	}
	return left, nil
}

// parseFactor -> num | '(' expr ')'
func (p *parser) parseFactor() (Node, error) {
