// Package lexer tokenizes a string of integer expression text.
package lexer

import "fmt"

// Token represents a single lexical token from the source.
type Token struct {
	Kind string // one of "num", "op", "lparen", "rparen"
	Text string // the source text of the token
}

// Tokens splits the input string into tokens, returning an error if any
// unrecognized characters are found.  Whitespace is skipped.
func Tokens(s string) ([]Token, error) {
	var toks []Token
	i := 0
	for i < len(s) {
		ch := s[i]

		// skip whitespace
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			i++
			continue
		}

		// digit → number (run of decimal digits)
		if ch >= '0' && ch <= '9' {
			j := i + 1
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			toks = append(toks, Token{"num", s[i:j]})
			i = j
			continue
		}

		// operators and parentheses
		switch ch {
		case '+', '-', '*', '/':
			toks = append(toks, Token{"op", string(ch)})
		case '(':
			toks = append(toks, Token{"lparen", "("})
		case ')':
			toks = append(toks, Token{"rparen", ")"})
		default:
			return nil, fmt.Errorf("unexpected character %q at position %d", ch, i)
		}
		i++
	}
	return toks, nil
}

