// Package parser builds an expression AST from lexer tokens.
package parser

import (
	"fmt"

	"example.com/expr/lexer"
)

// Node is an expression AST node.
type Node interface {
	isNode()
}

// Num represents a literal integer value.
type Num struct {
	Val int
}

func (Num) isNode() {}

// BinOp represents a binary operation: left, operator token text, right.
type BinOp struct {
	Op     string // "+", "-", "*", "/"
	Left   Node
	Right  Node
}

func (BinOp) isNode() {}

// Parser state
type parser struct {
	toks []lexer.Token
	pos  int
}

func newParser(toks []lexer.Token) *parser {
	return &parser{toks: toks, pos: 0}
}

// eof returns whether we have consumed all tokens.
func (p *parser) eof() bool { return p.pos >= len(p.toks) }

// peek returns the current token without consuming it, or nil if at end.
func (p *parser) peek() lexer.Token {
	if p.eof() {
		return lexer.Token{}
	}
	return p.toks[p.pos]
}

// consume advances past the current token and returns it.
func (p *parser) consume() lexer.Token {
	tok := p.toks[p.pos]
	p.pos++
	return tok
}

// Parse builds an AST from the given tokens.
// Supports + - * / with standard precedence (* / bind tighter than + -),
// left associativity, and parentheses grouping.
func Parse(toks []lexer.Token) (Node, error) {
	p := newParser(toks)
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if !p.eof() {
		return nil, fmt.Errorf("unexpected trailing input %q", p.peek().Text)
	}
	return node, nil
}

// parseExpr → term (("+" | "-") term)*
func (p *parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for !p.eof() {
		tok := p.peek()
		if tok.Kind != "op" || (tok.Text != "+" && tok.Text != "-") {
			break
		}
		op := p.consume().Text
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = BinOp{op, left, right}
	}
	return left, nil
}

// parseTerm → factor (("*" | "/") factor)*
func (p *parser) parseTerm() (Node, error) {
	left, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for !p.eof() {
		tok := p.peek()
		if tok.Kind != "op" || (tok.Text != "*" && tok.Text != "/") {
			break
		}
		op := p.consume().Text
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		left = BinOp{op, left, right}
	}
	return left, nil
}

// parseFactor → num | "(" expr ")"
func (p *parser) parseFactor() (Node, error) {
	if p.eof() {
		return nil, fmt.Errorf("missing operand")
	}
	tok := p.peek()
	switch tok.Kind {
	case "num":
		p.consume()
		var val int
		if _, err := fmt.Sscanf(tok.Text, "%d", &val); err != nil {
			return nil, fmt.Errorf("invalid number %q", tok.Text)
		}
		return Num{val}, nil
	case "lparen":
		p.consume() // consume '('
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if p.eof() || p.peek().Kind != "rparen" {
			return nil, fmt.Errorf("unclosed parenthesis")
		}
		p.consume() // consume ')'
		return expr, nil
	default:
		return nil, fmt.Errorf("unexpected token %q (%s)", tok.Text, tok.Kind)
	}
}

