package lexer

import (
	"fmt"
	"strings"
)

// Token represents a single lexical token.
type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string // source text of the token
}

// Tokens splits the input string into tokens. Returns an error for any
// unrecognized character. Whitespace is discarded.
func Tokens(s string) ([]Token, error) {
	var toks []Token
	i := 0
	for i < len(s) {
		ch := s[i]

		// Skip whitespace
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			i++
			continue
		}

		// Digit → number token
		if ch >= '0' && ch <= '9' {
			start := i
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
			toks = append(toks, Token{Kind: "num", Text: s[start:i]})
			continue
		}

		// Operator tokens
		switch ch {
		case '+', '-', '*', '/':
			toks = append(toks, Token{Kind: "op", Text: string(ch)})
			i++
			continue
		case '(':
			toks = append(toks, Token{Kind: "lparen", Text: "("})
			i++
			continue
		case ')':
			toks = append(toks, Token{Kind: "rparen", Text: ")"})
			i++
			continue
		default:
			return nil, fmt.Errorf("illegal character %q at position %d", ch, i)
		}
	}
	return toks, nil
}

// TrimmedLen returns the number of non-whitespace characters in s.
func trimmedLen(s string) int {
	count := 0
	for _, ch := range s {
		if ch != ' ' && ch != '\t' && ch != '\n' && ch != '\r' {
			count++
		}
	}
	return count
}

// HasLeadingOperator reports whether s starts with an operator after trimming whitespace.
func hasLeadingOperator(s string) bool {
	i := strings.IndexFunc(s, func(r rune) bool { return r != ' ' && r != '\t' && r != '\n' && r != '\r' })
	if i < 0 {
		return false
	}
	ch := s[i]
	return ch == '+' || ch == '-' || ch == '*' || ch == '/'
}

