package parser

import (
	"fmt"
	"strconv"

	"example.com/expr/lexer"
)

// Node represents an expression in the AST.
type Node interface {
	isNode()
}

// NumberNode holds an integer literal.
type NumberNode struct {
	Value int
}

func (NumberNode) isNode() {}

// BinaryOpNode holds a binary operation: left <op> right.
type BinaryOpNode struct {
	Left  Node
	Right Node
	Op    string // "+", "-", "*", "/"
}

func (BinaryOpNode) isNode() {}

// Parser drives recursive-descent parsing of token lists.
type Parser struct {
	toks []lexer.Token
	pos  int
}

// Parse parses the given token slice into an AST.
func Parse(toks []lexer.Token) (Node, error) {
	p := &Parser{toks: toks, pos: 0}
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, fmt.Errorf("unexpected trailing token %q (%s)", p.toks[p.pos].Text, p.toks[p.pos].Kind)
	}
	return node, nil
}

func (p *Parser) expect(kind string) (lexer.Token, error) {
	if p.pos >= len(p.toks) {
		return lexer.Token{}, fmt.Errorf("expected %s but reached end of input", kind)
	}
	tok := p.toks[p.pos]
	p.pos++
	if tok.Kind != kind {
		return lexer.Token{}, fmt.Errorf("expected %s but got %q (%s)", kind, tok.Text, tok.Kind)
	}
	return tok, nil
}

// parseExpr handles + and - at the lowest precedence, left associative.
func (p *Parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for p.pos < len(p.toks) && p.toks[p.pos].Kind == "op" &&
		(p.toks[p.pos].Text == "+" || p.toks[p.pos].Text == "-") {
		op := p.toks[p.pos].Text
		p.pos++
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = &BinaryOpNode{Left: left, Right: right, Op: op}
	}
	return left, nil
}

// parseTerm handles * and / at higher precedence, left associative.
func (p *Parser) parseTerm() (Node, error) {
	factor, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for p.pos < len(p.toks) && p.toks[p.pos].Kind == "op" &&
		(p.toks[p.pos].Text == "*" || p.toks[p.pos].Text == "/") {
		op := p.toks[p.pos].Text
		p.pos++
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		factor = &BinaryOpNode{Left: factor, Right: right, Op: op}
	}
	return factor, nil
}

// parseFactor handles atoms: numbers and parenthesized sub-expressions.
func (p *Parser) parseFactor() (Node, error) {
	if p.pos >= len(p.toks) {
		return nil, fmt.Errorf("unexpected end of input while expecting a factor")
	}
	tok := p.toks[p.pos]

	switch tok.Kind {
	case "num":
		p.pos++
		val, err := strconv.Atoi(tok.Text)
		if err != nil {
			return nil, fmt.Errorf("invalid number %q: %w", tok.Text, err)
		}
		return &NumberNode{Value: val}, nil

	case "lparen":
		p.pos++ // consume '('
		node, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		_, err = p.expect("rparen")
		if err != nil {
			return nil, err
		}
		return node, nil

	default:
		return nil, fmt.Errorf("unexpected token %q (%s) while expecting a factor", tok.Text, tok.Kind)
	}
}

