package eval

import (
	"fmt"

	"example.com/expr/parser"
)

// Eval evaluates the given parse tree node and returns its integer value.
func Eval(n parser.Node) (int, error) {
	switch node := n.(type) {
	case *parser.NumberNode:
		return node.Value, nil

	case *parser.BinaryOpNode:
		left, err := Eval(node.Left)
		if err != nil {
			return 0, err
		}
		right, err := Eval(node.Right)
		if err != nil {
			return 0, err
		}

		switch node.Op {
		case "+":
			return left + right, nil
		case "-":
			return left - right, nil
		case "*":
			return left * right, nil
		case "/":
			if right == 0 {
				return 0, fmt.Errorf("division by zero")
			}
			return left / right, nil
		default:
			return 0, fmt.Errorf("unknown operator %q", node.Op)
		}

	default:
		return 0, fmt.Errorf("unknown node type %T", n)
	}
}

