// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	mu      sync.Mutex
	cond    *sync.Cond
	compute func(string) int
	cache   map[string]int
	calls   int
	busy    map[string]bool // tracks keys currently being computed
	outMu   sync.Mutex      // protects All's output map
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	fm := &Fetcher{
		compute: f,
		cache:   map[string]int{},
		busy:    map[string]bool{},
	}
	fm.cond = sync.NewCond(&fm.mu)
	return fm
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	for {
		f.mu.Lock()

		// Already cached?
		if v, ok := f.cache[k]; ok {
			f.mu.Unlock()
			return v
		}

		// Is someone else computing this?
		if f.busy[k] {
			f.cond.Wait()
			f.mu.Unlock()
			continue
		}

		// Nobody is computing; we win.
		f.busy[k] = true
		f.mu.Unlock()

		// Compute outside the lock so distinct keys proceed in parallel.
		v := f.compute(k)

		f.mu.Lock()
		f.calls++
		f.cache[k] = v
		delete(f.busy, k)
		f.cond.Broadcast()
		f.mu.Unlock()

		return v
	}
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.calls
}

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			v := f.Get(k)
			f.outMu.Lock()
			out[k] = v
			f.outMu.Unlock()
		}(k)
	}
	wg.Wait()
	return out
}

