package fetch

import "sync"

// keyLock guards a single cache key so that its compute runs exactly once.
type keyLock struct {
	mu sync.Mutex
}

// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	mu      sync.Mutex
	compute func(string) int
	cache   map[string]int
	calls   int
	locks   map[string]*keyLock
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	return &Fetcher{compute: f, cache: map[string]int{}, locks: map[string]*keyLock{}}
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	f.mu.Lock()
	if v, ok := f.cache[k]; ok {
		f.mu.Unlock()
		return v
	}
	lk, ok := f.locks[k]
	if !ok {
		lk = &keyLock{}
		f.locks[k] = lk
	}
	f.mu.Unlock()

	lk.mu.Lock()

	f.mu.Lock()
	if v, ok := f.cache[k]; ok {
		f.mu.Unlock()
		lk.mu.Unlock()
		return v
	}
	f.calls++
	f.mu.Unlock()

	v := f.compute(k)

	f.mu.Lock()
	f.cache[k] = v
	f.mu.Unlock()

	lk.mu.Unlock()

	return v
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.calls
}

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var mu sync.Mutex
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			v := f.Get(k)
			mu.Lock()
			out[k] = v
			mu.Unlock()
		}(k)
	}
	wg.Wait()
	return out
}

