'use strict';

function parseVersion(v) {
  if (typeof v !== 'string') throw new Error('version must be a string');
  var s = v.trim();
  var m = s.match(/^(\d+)\.(\d+)\.(\d+)$/);
  if (!m) throw new Error('invalid semver: ' + v);
  return [parseInt(m[1], 10), parseInt(m[2], 10), parseInt(m[3], 10)];
}

function compare(a, b) {
  var av = parseVersion(a);
  var bv = parseVersion(b);
  for (var i = 0; i < 3; i++) {
    if (av[i] < bv[i]) return -1;
    if (av[i] > bv[i]) return 1;
  }
  return 0;
}

function satisfies(version, range) {
  var v = parseVersion(version);
  var r = range.trim();

  // bare version – equality
  if (!r.match(/[\^\*\>\<\=]/)) {
    var target = parseVersion(r);
    return compare(version, r) === 0;
  }

  // wildcard
  if (r === '*') return true;

  // prefix operator
  var op, verStr;
  if (r[0] === '^') {
    op = '^';
    verStr = r.substring(1);
  } else if (r[0] === '~') {
    op = '~';
    verStr = r.substring(1);
  } else if (r.indexOf('>=') === 0) {
    op = '>=';
    verStr = r.substring(2);
  } else if (r.indexOf('>') === 0) {
    op = '>';
    verStr = r.substring(1);
  } else if (r.indexOf('<=') === 0) {
    op = '<=';
    verStr = r.substring(2);
  } else if (r.indexOf('<') === 0) {
    op = '<';
    verStr = r.substring(1);
  } else {
    throw new Error('invalid range: ' + range);
  }

  var target = parseVersion(verStr);

  if (op === '^') {
    // lower bound: target
    if (compare(version, r.substring(1)) < 0) return false;
    // upper bound: next boundary of leftmost non-zero field
    var lo = target.slice();
    var ub = lo.slice();
    if (ub[0] !== 0) {
      ub[0]++; ub[1] = 0; ub[2] = 0;
    } else if (ub[1] !== 0) {
      ub[1]++; ub[2] = 0;
    } else {
      ub[2]++;
    }
    return compare(version, ub.join('.')) < 0;
  }

  if (op === '~') {
    // lower bound: target
    if (compare(version, r.substring(1)) < 0) return false;
    // upper bound: X.(Y+1).0
    var ub = [target[0], target[1] + 1, 0];
    return compare(version, ub.join('.')) < 0;
  }

  if (op === '>=') return compare(version, verStr) >= 0;
  if (op === '>')  return compare(version, verStr) > 0;
  if (op === '<=') return compare(version, verStr) <= 0;
  if (op === '<')  return compare(version, verStr) < 0;
}

module.exports = { compare: compare, satisfies: satisfies };

