'use strict';

function parseVersion(v) {
  if (typeof v !== 'string') throw new Error('version must be a string');
  var s = v.trim();
  var m = s.match(/^(\d+)\.(\d+)\.(\d+)$/);
  if (!m) throw new Error('invalid semver: ' + v);
  return [parseInt(m[1], 10), parseInt(m[2], 10), parseInt(m[3], 10)];
}

function compare(a, b) {
  var av = parseVersion(a);
  var bv = parseVersion(b);
  for (var i = 0; i < 3; i++) {
    if (av[i] < bv[i]) return -1;
    if (av[i] > bv[i]) return 1;
  }
  return 0;
}

function satisfies(version, range) {
  var verStr = version.toString();
  var r = range.trim();

  // Detect operator prefix
  if (r === '*') return true;

  var op, verArg;
  if (r.indexOf('^') === 0) {
    op = '^';
    verArg = r.substring(1);
  } else if (r.indexOf('~') === 0) {
    op = '~';
    verArg = r.substring(1);
  } else if (r.indexOf('>=') === 0) {
    op = '>=';
    verArg = r.substring(2);
  } else if (r.indexOf('<=') === 0) {
    op = '<=';
    verArg = r.substring(2);
  } else if (r.indexOf('>') === 0) {
    op = '>';
    verArg = r.substring(1);
  } else if (r.indexOf('<') === 0) {
    op = '<';
    verArg = r.substring(1);
  } else {
    // bare version – treat as equality
    op = '==';
    verArg = r;
  }

  // Parse both the target version and the input version to validate
  var target = parseVersion(verArg);
  var vnum = parseVersion(verStr);

  if (op === '==') {
    return compare(verStr, verArg) === 0;
  }
  if (op === '^') {
    // At least target AND less than next boundary
    if (compare(verStr, verArg) < 0) return false;
    var ub = target.slice();
    if (ub[0] !== 0) {
      ub[0]++; ub[1] = 0; ub[2] = 0;
    } else if (ub[1] !== 0) {
      ub[1]++; ub[2] = 0;
    } else {
      ub[2]++;
    }
    return compare(verStr, ub.join('.')) < 0;
  }
  if (op === '~') {
    // At least target AND less than X.(Y+1).0
    if (compare(verStr, verArg) < 0) return false;
    var ub2 = [target[0], target[1] + 1, 0];
    return compare(verStr, ub2.join('.')) < 0;
  }
  if (op === '>=') return compare(verStr, verArg) >= 0;
  if (op === '>')  return compare(verStr, verArg) > 0;
  if (op === '<=') return compare(verStr, verArg) <= 0;
  if (op === '<')  return compare(verStr, verArg) < 0;
}

module.exports = { compare: compare, satisfies: satisfies };

