'use strict';

var semver = require('./semver');

var args = process.argv.slice(2);
var cmd = args[0];

try {
  if (cmd === 'compare') {
    if (args.length !== 3) throw new Error('Usage: node cli.js compare A B');
    var result = semver.compare(args[1], args[2]);
    process.stdout.write(result.toString() + '\n');
  } else if (cmd === 'satisfies') {
    if (args.length !== 3) throw new Error('Usage: node cli.js satisfies V RANGE');
    var ok = semver.satisfies(args[1], args[2]);
    process.stdout.write((ok ? 'true' : 'false') + '\n');
  } else {
    throw new Error('Unknown command: ' + cmd);
  }
} catch (err) {
  process.stderr.write(err.message + '\n');
  process.exit(1);
}

