'use strict';

/**
 * Parse a version string into [major, minor, patch] numbers.
 * Throws on any non-conforming input.
 */
function parseVersion(v) {
  if (typeof v !== 'string') {
    throw new Error('Version must be a string');
  }
  v = v.trim();
  var m = v.match(/^(\d+)\.(\d+)\.(\d+)$/);
  if (!m) {
    throw new Error('Invalid version: ' + v);
  }
  return [parseInt(m[1], 10), parseInt(m[2], 10), parseInt(m[3], 10)];
}

/**
 * Compare two semver strings. Returns -1, 0 or 1.
 */
function compare(a, b) {
  var aa = parseVersion(a);
  var bb = parseVersion(b);
  for (var i = 0; i < 3; i++) {
    if (aa[i] < bb[i]) return -1;
    if (aa[i] > bb[i]) return 1;
  }
  return 0;
}

/**
 * Check whether version satisfies the given range.
 *
 * Supported ranges:
 *   *                        – match anything
 *   X.Y.Z                    – exact match
 *   ^X.Y.Z                   – compatible with (at least X.Y.Z, below next change)
 *   ~X.Y.Z                   – approximately (at least X.Y.Z, below Y+1.0)
 *   >=X.Y.Z  |  >X.Y.Z       – comparison operators
 *   <=X.Y.Z  |  <X.Y.Z
 */
function satisfies(version, range) {
  range = typeof range === 'string' ? range.trim() : range;

  // bare wildcard
  if (range === '*') return true;

  // try to detect an operator prefix
  var opMatch = range.match(/^(>=|<=|>|<)\s*(.+)$/);
  if (opMatch) {
    var cv = parseVersion(opMatch[2]);
    var cmp = compare(version, opMatch[2]);
    switch (opMatch[1]) {
      case '>=': return cmp >= 0;
      case '<=': return cmp <= 0;
      case '>':  return cmp > 0;
      case '<':  return cmp < 0;
    }
  }

  // caret range ^X.Y.Z
  if (range.charAt(0) === '^') {
    var base = parseVersion(range.slice(1));
    var cv = parseVersion(version);
    if (compare(version, base) < 0) return false;

    // find the upper bound: bump the leftmost non-zero field
    var upper = [base[0], base[1], base[2]];
    if (upper[0] !== 0) {
      upper[0]++;
      upper[1] = 0;
      upper[2] = 0;
    } else if (upper[1] !== 0) {
      upper[1]++;
      upper[2] = 0;
    } else {
      upper[2]++;
    }

    return compare(version, '.' + upper.join('.')) < 0;
  }

  // tilde range ~X.Y.Z
  if (range.charAt(0) === '~') {
    var base2 = parseVersion(range.slice(1));
    var cv2 = parseVersion(version);
    if (compare(version, base2) < 0) return false;
    // upper bound is X.(Y+1).0
    var hiMajor = base2[0];
    var hiMinor = base2[1] + 1;
    return compare(version, '.' + hiMajor + '.' + hiMinor + '.0') < 0;
  }

  // bare version – exact match
  return compare(version, range) === 0;
}

module.exports = { compare: compare, satisfies: satisfies };

