'use strict';

var semver = require('./semver');

var args = process.argv.slice(2);

if (args.length < 1) {
  process.stderr.write('Usage: cli.js <command> [args...]\n', function() { process.exit(1); });
  process.exit(1);
}

var command = args[0];

try {
  if (command === 'compare') {
    if (args.length !== 3) {
      throw new Error('compare requires exactly 2 arguments');
    }
    var result = semver.compare(args[1], args[2]);
    process.stdout.write(String(result) + '\n');
  } else if (command === 'satisfies') {
    if (args.length !== 3) {
      throw new Error('satisfies requires version and range arguments');
    }
    var ok = semver.satisfies(args[1], args[2]);
    process.stdout.write(String(ok) + '\n');
  } else {
    throw new Error('Unknown command: ' + command);
  }
} catch (err) {
  process.stderr.write(err.message + '\n');
  process.exit(1);
}

