'use strict';

var semver = require('./semver');
var passed = 0, failed = 0;

function assert(cond, msg) {
  if (cond) { passed++; } else { failed++; console.log('FAIL:', msg); }
}

// ---- compare tests ----
assert(semver.compare('1.2.3', '1.2.4') === -1, 'compare: 1.2.3 < 1.2.4');
assert(semver.compare('1.2.3', '1.2.3') === 0, 'compare: 1.2.3 == 1.2.3');
assert(semver.compare('2.0.0', '1.9.9') === 1, 'compare: 2.0.0 > 1.9.9');
assert(semver.compare('1.10.0', '1.9.0') === 1, 'compare: 1.10.0 > 1.9.0 (numeric)');
assert(semver.compare(' 1.2.3 ', '1.2.3') === 0, 'compare: whitespace trimmed');

try { semver.compare('1.2', '1.2.3'); assert(false, 'compare: two-fields should throw'); } catch(e) {}
try { semver.compare('1.2.3.4', '1.2.3'); assert(false, 'compare: four-fields should throw'); } catch(e) {}
try { semver.compare('v1.2.3', '1.2.3'); assert(false, 'compare: v-prefix should throw'); } catch(e) {}
try { semver.compare(123, '1.2.3'); assert(false, 'compare: non-string should throw'); } catch(e) {}
try { semver.compare('1.2.3', 123); assert(false, 'compare: second arg non-string should throw'); } catch(e) {}

// satisfies: bare version
assert(semver.satisfies('1.2.3', '1.2.3') === true, 'satisfies: exact match');
assert(semver.satisfies('1.2.4', '1.2.3') === false, 'satisfies: not exact match');

// satisfies: star
assert(semver.satisfies('99.99.99', '*') === true, 'satisfies: * matches anything');
assert(semver.satisfies('1.2.3', '*') === true, 'satisfies: * matches 1.2.3');

