/**
 * Check if version array is in the half-open interval [lo, hi).
 * All are arrays of [M, I, P].
 */
function inRangeParts(vers, lo, hi) {
  // vers >= lo ?
  for (var i = 0; i < 3; i++) {
    if (vers[i] > lo[i]) break;
    if (vers[i] < lo[i]) return false;
  }
  // vers < hi ?
  for (var i = 0; i < 3; i++) {
    if (vers[i] < hi[i]) return true;
    if (vers[i] > hi[i]) return false;
  }
  // equal to hi -> not in range
  return false;
}

