'use strict';

/**
 * Parse and validate a version string "MAJOR.MINOR.PATCH".
 * Returns [major, minor, patch] as numbers or throws.
 */
function parseVersion(input) {
  if (typeof input !== 'string') {
    throw new Error('Version must be a string: ' + JSON.stringify(input));
  }
  var trimmed = input.trim();
  // Must be exactly three numeric fields separated by dots
  var m = trimmed.match(/^(\d+)\.(\d+)\.(\d+)$/);
  if (!m) {
    throw new Error('Invalid version: ' + JSON.stringify(input));
  }
  return [parseInt(m[1], 10), parseInt(m[2], 10), parseInt(m[3], 10)];
}

/**
 * Compare two semver strings. Returns -1, 0, or 1.
 */
function compare(a, b) {
  var va = parseVersion(a);
  var vb = parseVersion(b);
  for (var i = 0; i < 3; i++) {
    if (va[i] < vb[i]) return -1;
    if (va[i] > vb[i]) return 1;
  }
  return 0;
}

/**
 * Compare two parsed version arrays. Returns -1, 0, or 1.
 */
function compareParts(va, vb) {
  for (var i = 0; i < 3; i++) {
    if (va[i] < vb[i]) return -1;
    if (va[i] > vb[i]) return 1;
  }
  return 0;
}

/**
 * Compute the upper bound exclusive for ^X.Y.Z.
 * Find the leftmost non-zero field and bump it.
 */
function halfOpenUpCaret(parts) {
  var major = parts[0], minor = parts[1], patch = parts[2];
  if (major !== 0) {
    return [major + 1, 0, 0];
  }
  if (minor !== 0) {
    return [0, minor + 1, 0];
  }
  return [0, 0, patch + 1];
}

/**
 * Compute the upper bound exclusive for ~X.Y.Z -> X.(Y+1).0
 */
function halfOpenUpTilde(parts) {
  return [parts[0], parts[1] + 1, 0];
}

/**
 * Check if version array is in the half-open interval [lo, hi).
 * All are arrays of [M, I, P].
 */
function inRangeParts(vers, lo, hi) {
  // vers >= lo ?
  var cmpLo = compareParts(vers, lo);
  if (cmpLo < 0) return false;
  // vers < hi ?
  return compareParts(vers, hi) < 0;
}

/**
 * Parse a range specifier into either {type:'version'} or an object with bounds.
 * Throws on anything invalid.
 */
function parseRange(rangeInput) {
  if (typeof rangeInput !== 'string') {
    throw new Error('Range must be a string: ' + JSON.stringify(rangeInput));
  }
  var trimmed = rangeInput.trim();

  // bare wildcard
  if (trimmed === '*') {
    return { type: 'star' };
  }

  // caret range: ^X.Y.Z
  if (trimmed.charAt(0) === '^') {
    var baseC = parseVersion(trimmed.substring(1));
    return {
      type: 'caret',
      lo: baseC,
      hi: halfOpenUpCaret(baseC)
    };
  }

  // tilde range: ~X.Y.Z
  if (trimmed.charAt(0) === '~') {
    var baseT = parseVersion(trimmed.substring(1));
    return {
      type: 'tilde',
      lo: baseT,
      hi: halfOpenUpTilde(baseT)
    };
  }

  // operator ranges: >=, >, <=, < followed by version
  var opMatch = trimmed.match(/^(>=|>|<=|<)(.+)$/);
  if (opMatch) {
    return {
      type: 'op',
      op: opMatch[1],
      target: parseVersion(opMatch[2])
    };
  }

